export const useAllowedHostNames = () => {
  'use memo';
  const baiClient = useConnectedBAIClient();
  const { data } = useSuspenseTanQuery({
    queryKey: ['useAllowedHOstNames'],
    queryFn: () => baiClient.vfolder.list_all_hosts(),
  });
  return data?.allowed;
};

