export function useMutationWithPromise<T extends MutationParameters>(
  mutation: GraphQLTaggedNode,
) {
  const environment = useRelayEnvironment();
  return (variables: T['variables']) => {
    return new Promise<T['response']>((resolve, reject) => {
      commitMutation<T>(environment, {
        mutation,
        variables,
        onCompleted: (response, errors) => {
          if (errors) {
            // A `data` + `errors` response: surface the GraphQL messages as an
            // Error so `getErrorMessage` / `error.message` readers see them.
            reject(new Error(errors.map((e) => e.message).join('\n')));
          } else {
            resolve(response);
          }
        },
        onError: (error) => {
          reject(error);
        },
      });
    });
  };
}
