'use client';

/**
 * @file useLayerDismissal.ts
 * @input Uses React hooks, the layer stack, and LayerDepthContext
 * @output Exports useLayerDismissal + its option/return types
 * @position The API overlays use to join the shared dismissal stack. Wraps
 *   layerStack (registration + the single Escape listener) and reads nesting
 *   depth from LayerDepthContext.
 *
 * SYNC: When modified, update:
 * - /packages/core/src/Layer/index.ts
 * - /packages/core/src/Layer/useLayerDismissal.test.tsx
 * - /packages/core/src/Layer/layerStack.ts
 */
import { useCallback, useEffect, useRef } from 'react';
import { useLayerDepth } from "./LayerDepthContext.js";
import { isTextComposing, isTopmostLayer, registerLayer } from "./layerStack.js";
/**
 * Join the shared layer dismissal stack for as long as this layer is active.
 *
 * The layer does NOT attach a key listener — the stack owns one listener and
 * routes each Escape press to the top-most REGISTERED layer, so one press
 * dismisses exactly one of them. Dialog (and what is built on it), Popover and
 * the menus built on it, Tooltip, HoverCard, Lightbox, MobileNav, BottomSheet,
 * BottomSheetSwitcher and lab's `Drawer` register today.
 *
 * `CommandPalette`, `ContextMenu`, `DropdownMenuSubMenu`, and
 * `PowerSearchEditPopover` still run their own Escape listeners. They stay safe
 * next to the stack only because each claims the press at element level, and the
 * stack stands down on an already-`defaultPrevented` press — but a registered
 * layer opened inside one of them does not get the press. Migrating them is the
 * fix.
 *
 * Wrap the layer's own content in `LayerDepthProvider` so anything opened from
 * inside it registers as nested.
 *
 * @example
 * ```tsx
 * useLayerDismissal({
 *   isActive: isOpen,
 *   onDismiss: () => onOpenChange(false),
 * });
 * ```
 */
export function useLayerDismissal(options) {
  const {
    isActive,
    onDismiss,
    escapeBehavior = 'close',
    getContainer,
    isPresent,
    isEnabled = true
  } = options;
  const depth = useLayerDepth();

  // Identity remains stable while one active layer re-registers because its
  // depth or behavior changed. A later inactive -> active cycle gets a fresh
  // identity below so its registration order matches a newly shown top-layer
  // host rather than the component's original mount order.
  const tokenRef = useRef({});
  const wasRegisteredRef = useRef(false);

  // The stack calls these during an event, outside React's render, so they must
  // reach the latest closures rather than the ones captured at registration.
  const onDismissRef = useRef(onDismiss);
  const getContainerRef = useRef(getContainer);
  const isPresentRef = useRef(isPresent);
  useEffect(() => {
    onDismissRef.current = onDismiss;
    getContainerRef.current = getContainer;
    isPresentRef.current = isPresent;
  });
  const isRegistered = isActive && isEnabled;
  useEffect(() => {
    if (!isRegistered) {
      wasRegisteredRef.current = false;
      return;
    }
    if (!wasRegisteredRef.current) {
      tokenRef.current = {};
      wasRegisteredRef.current = true;
    }
    return registerLayer({
      token: tokenRef.current,
      depth,
      behavior: escapeBehavior,
      getContainer: () => getContainerRef.current?.() ?? null,
      isPresent: () => isPresentRef.current?.() ?? true,
      dismiss: () => onDismissRef.current()
    });
  }, [isRegistered, depth, escapeBehavior]);
  const shouldDismissOnCloseRequest = useCallback(() => isRegistered && !isTextComposing() && isTopmostLayer(tokenRef.current), [isRegistered]);
  return {
    shouldDismissOnCloseRequest
  };
}